/**
 * Reading priors: for the commonest written forms, which (lemma, group) the training treebanks read them as (priors-data.ts, generated by
 * scripts/latin-build-priors.mjs). Loaded lazily with the full lexicon. A reading the analyser already has is boosted when it matches; a
 * reading is never added, and a form the table does not know is left as the lexicon's own frequencies rank it.
 */
import type { PartOfSpeech } from '../../core';
import { foldKey } from './orthography';

interface Entry { total: number; by: Map<string, number> }
let table: Map<string, Entry> | undefined;

export function installPriors(text: string): number {
  const m = new Map<string, Entry>();
  for (const line of text.split('\n')) {
    const [key, total, readings] = line.split('\t');
    if (!key || !readings) continue;
    const by = new Map<string, number>();
    for (const r of readings.split(' ')) {
      const i = r.lastIndexOf(':');
      by.set(r.slice(0, i), Number(r.slice(i + 1)));
    }
    m.set(key, { total: Number(total), by });
  }
  table = m;
  return m.size;
}

export const priorsInstalled = (): boolean => table !== undefined;

const GROUPS: Partial<Record<PartOfSpeech, string[]>> = {
  NOUN: ['N'], PROPN: ['N'], VERB: ['V'], AUX: ['V'], ADJ: ['A', 'P'], DET: ['P', 'A'], ADV: ['D'], PART: ['D'], CONJ: ['C'], SCONJ: ['C'], ADP: ['R'], PRON: ['P'], NUM: ['M', 'A'], INTJ: ['I'],
};

/** Multiplier for a reading of `key` as (lemma, pos): 1 when the table has nothing on the form or the reading. */
export function priorBoost(key: string, lemma: string, pos: PartOfSpeech): number {
  if (!table) return 1;
  const e = table.get(key);
  if (!e) return 1;
  const l = foldKey(lemma);
  let n = 0;
  for (const g of GROUPS[pos] ?? []) n = Math.max(n, e.by.get(`${l}:${g}`) ?? 0);
  if (!n) return 1;
  return 1 + 14 * (n / e.total);
}
